import{_ as E,H as e,f as t,i as B}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"结束语-你的变化，就是数字时代的一个缩影","description":"","frontmatter":{},"headers":[],"relativePath":"人人都用得上的数字化思维课/结束语-你的变化，就是数字时代的一个缩影.md","filePath":"人人都用得上的数字化思维课/结束语-你的变化，就是数字时代的一个缩影.md","lastUpdated":1795541641000}'),a={name:"人人都用得上的数字化思维课/结束语-你的变化，就是数字时代的一个缩影.md"};function A(_,p,s,n,i,r){return e(),t("div",null,[...p[0]||(p[0]=[B('<h1 id="结束语-你的变化-就是数字时代的一个缩影" tabindex="-1">结束语-你的变化，就是数字时代的一个缩影 <a class="header-anchor" href="#结束语-你的变化-就是数字时代的一个缩影" aria-label="Permalink to &quot;结束语-你的变化，就是数字时代的一个缩影&quot;">​</a></h1><p>你好，我是付晓岩。</p><p>《人人都用得上的数字化思维课》到今天就更新结束了。在过去的 4 周时间里，咱们一起从认知、个体技能和展望这 3 个维度学习了啥是数字化，以及个体如何转型才能应对数字化时代的变化。</p><p>这门课进行到这里，希望我们不用再觉得“时代的变化”是一件离我们很远的事儿了。它是由咱们每个人共同创造的，你影响我、我影响你，时代的变化就这么来了。</p><p>在写这两门以数字化转型为主题的专栏课的过程中，我接触了很多想做或者在做数字化的同学，其中有不少同学表示自己一直不理解到底啥是数字化、为啥一定要做数字化。关于这些问题的争论，有时会聚焦在一个点上，比如通用人工智能的实现方式；有时又会发散到管理、人文的层面，比如通用人工智能引发的工作环境的变化；有时还会涉及一个颇为古老的话题，机器效率提升导致的失业，而这是从工业时代早期就被讨论，至今仍时常会焕发新生的话题。</p><p>时代的变化总会带来各种思考和憧憬，也有各种迷乱和困惑，这也是为什么再次写数字化转型课程时，课程名称里会有“人人都用得上”这个前缀的原因。我希望能够在个人发展层面，让屏幕前的每一个“你”都不再纠结到底啥是数字化，而是聚焦到怎么做才一定能帮自己走到数字化的方向上。</p><p>尽管对数字化的理解不能脱离开宏大的时代背景，但是“大处着眼，小处着手”，我希望能帮你在了解大时代背景的情况下，聚焦到个人能力的提升上。这就是我在课程里反复提到数据、工具和网络的原因了。</p><p>在开篇词中，我也分享过我自己是在这条路上一步步实践过的人。我是从业务领域转型到技术领域的，在06 讲介绍数字化人才分类时，我提到过业务架构师其实是很难培养的一类人才。回想自己这 10 年业务架构的“驾龄”，一路走来确实不容易，这里我便和你分享下自己转型的心得。我的经验虽然不能被复制，但相信有很多方法是通用的，希望能对你有所启发。</p><p>首先，一个人的转型一定离不开的就是学习。</p><p>我算是比较幸运的，当我对技术领域的工作产生兴趣要转行时，赶上了前东家启动大型企业级工程。这次工程中缺少的一个非常重要的角色，就是业务架构师。我们当时采用的是传统开发模式，只有“需求分析”这个岗位是接触业务侧比较多的技术类人员。</p><p>没错，我最初转行时就是需求分析岗，但是工程实施方式的改变，我直接被推向了业务架构师。好在这个项目有咨询公司支持，我们跟着咨询公司学习怎么做业务架构设计，有指导、有实践，条件还算挺好的。但是，这些对于培养一个好的业务架构师来说，还远远不够。所以，我自己又去阅读了大量工程类、系统分析类的书籍。同时，业务架构师也要对一些技术有比较深入的了解，比如区块链的应用前景。</p><p>在这一过程中，我接触到了作为业务人员来讲，陌生又熟悉的一个领域，也就是数据，特别是对数据的建模。结合数据的业务流程分析，使我更加容易理解大家经常提到的“一切业务数据化，一切数据业务化”是什么意思，以及如何去实现它。这是在这门课程我一直在强调关注数据的原因，也是我理解为什么国家政策会将数据当作新生产要素的原因。</p><p>这个转型过程，花了我六年左右的时间。因此，我极度相信深入实践、长期坚守的价值。</p><p>其次，提升理解的最好方式是分享。</p><p>在 2012～2018 年这 6 年的转型过程中，我的精力主要集中在企业内部实践上，包括如何设计好业务架构、如何落地架构设计、如何管理好架构资产、如何提升基于架构资产的工作效率。</p><p>从 2019 年开始，我陆续出版业务架构、数字化转型、企业架构相关的书籍、专栏课，分享公众号文章、自制短视频、参加大会演讲和讲授培训课程。这些活动让我对这些知识的理解完全换了一个角度，要从自己理解转到让更多的人理解，尤其是让很多没有和我相同经历的人理解。这个过程很有挑战，但也给我带来了很大的提升，结识了很多朋友，扩展了对实践的理解。</p><p>现在我非常认同这样一句话，“分享创造价值，价值创造连接”，而连接又会带来更高质量的网络。我自己对网络和生态的价值深有体会，所以我在课程里也多次讲到网络和生态。</p><p>再次，很困难却很重要的一点是，要建立合理的思维和行为模式。</p><p>最近在一次闭门沙龙会上，又听到对现有企业经营管理模式的一些反思，比如创新“拍胸脯”、决策“拍脑袋”等。其实，这些年我们至少在观念上对数据的重视已经增强了很多，那为啥还会有这样的反思呢。在我看来，就是思维还没有完全到位，思维和行为之间还有差距，没有到“知行合一”的境界。</p><p>数据虽然本身不带结论，但却是我们作结论要努力参考的。每个人的大多数行为其实都是面向未来的，是当下执行未来产生后果，无论这个未来的时间间隔是小到瞬息还是大到数年。每个人都在预测或者预期未来，而很多行为的后果，其实都可以基于经验数据看到个大概，所以参考历史数据很重要。当然，分析工具也是必备的。</p><p>同时，要想通过数据得出合理的结论，还需要我们有全局观的思维模式，也就是说，很多事情可能会交织在一起。举个例子吧。你现在要去参加一场很重要的活动，基于历史数据半个小时就可以到现场，但如果考虑堵车的话，你可能要提前一个小时出发。</p><p>这个例子很好理解，目的就是想和你说，全局观其实并不难，就是遇事多想一点儿。如果我们希望能想得更全一些，那除了经验之外还需要有意识地建立思考模式。比如，在分析问题时，我会坚持用企业架构的思考模式，先针对问题建立相对完整的背景分析。所以，对数字化转型问题的思考，我会去看几年乃至十几年之后的变化，因为拉长时间周期是个全面认识问题的好方法。还记得咱们在01 讲学习的时间和空间的全局性吗？这就是动态的、全局的思考方式。</p><p>最后，思考落到行为上，就是对自己信念的坚持了。</p><p>这种坚持也需要用到架构思维中的一些关键点，比如灵活、演进。我们坚持信念，但也必须灵活实践。咱们每个人处理自己的工作、生活，都是在做应用题，而不是为了给某个方法增加个案例做一道证明题。所以，对于道理、知识的运用，都是建立在我们所处的实际场景中的。我把这门课最后定位在“思维课”上，也是这个原因。</p><p>我希望你理解我说的，不要觉得数字化的概念很大、很神秘，数字化相关的政策、企业转型案例离自己很远，或者觉得自己现在要参与到转型中有太多需要补充的知识而非常焦虑，其实你只要做好自己就够了。</p><p>还是那句话，时代的变化，一定会让身处其中的每个人真正地感受到生产、生活方式的变化，而不是只看到各种对概念的解读和争论。真相就在你身边，真知就在你心里，你的变化就是数字时代的一个缩影。</p><p>另外，我还给你准备了一份毕业问卷，希望你能花两三分钟填写一下，非常期待能听到你对这门课的反馈。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84%E6%95%B0%E5%AD%97%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD-%25E4%25BD%25A0%25E7%259A%2584%25E5%258F%2598%25E5%258C%2596%25EF%25BC%258C%25E5%25B0%25B1%25E6%2598%25AF%25E6%2595%25B0%25E5%25AD%2597%25E6%2597%25B6%25E4%25BB%25A3%25E7%259A%2584%25E4%25B8%2580%25E4%25B8%25AA%25E7%25BC%25A9%25E5%25BD%25B1/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84%E6%95%B0%E5%AD%97%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD-%25E4%25BD%25A0%25E7%259A%2584%25E5%258F%2598%25E5%258C%2596%25EF%25BC%258C%25E5%25B0%25B1%25E6%2598%25AF%25E6%2595%25B0%25E5%25AD%2597%25E6%2597%25B6%25E4%25BB%25A3%25E7%259A%2584%25E4%25B8%2580%25E4%25B8%25AA%25E7%25BC%25A9%25E5%25BD%25B1/1.png" alt=""></a></p>',28)])])}const l=E(a,[["render",A]]);export{c as __pageData,l as default};
